const assert = require('node:assert/strict');
const { DocumentRepository } = require('../.build/repository');
const { DocumentService } = require('../.build/service');

function setup(docs) {
  const repo = new DocumentRepository(docs.map(d => ({ deleted: false, archived: false, ...d })));
  return { repo, service: new DocumentService(repo) };
}
const snapshot = repo => JSON.stringify({ docs: repo.documents, audit: repo.audit });

const admin = { tenant: 'a', user: 'adm', role: 'admin' };
const editor = { tenant: 'a', user: 'ed', role: 'editor' };
const viewer = { tenant: 'a', user: 'vw', role: 'viewer' };

// Admin archives any visible document, including ones owned by others.
{
  const { repo, service } = setup([{ id: 'x', tenant: 'a', owner: 'other' }]);
  service.archive(admin, 'x');
  assert.equal(repo.documents[0].archived, true);
  assert.deepEqual(repo.audit, [{ actor: 'adm', document: 'x' }]);
}

// Editor archives only own documents.
{
  const { repo, service } = setup([
    { id: 'mine', tenant: 'a', owner: 'ed' },
    { id: 'theirs', tenant: 'a', owner: 'other' },
  ]);
  assert.throws(() => service.archive(editor, 'theirs'), { message: 'forbidden' });
  assert.equal(repo.documents[1].archived, false);
  service.archive(editor, 'mine');
  assert.deepEqual(repo.audit, [{ actor: 'ed', document: 'mine' }]);
}

// Viewer may never archive, even own documents.
{
  const { repo, service } = setup([{ id: 'v', tenant: 'a', owner: 'vw' }]);
  assert.throws(() => service.archive(viewer, 'v'), { message: 'forbidden' });
  assert.equal(repo.documents[0].archived, false);
  assert.deepEqual(repo.audit, []);
}

// Missing, deleted and foreign-tenant documents are "not found" for every role.
{
  const { repo, service } = setup([
    { id: 'del', tenant: 'a', owner: 'adm', deleted: true },
    { id: 'foreign', tenant: 'b', owner: 'adm' },
  ]);
  const before = snapshot(repo);
  for (const actor of [admin, editor, viewer]) {
    for (const id of ['missing', 'del', 'foreign']) {
      assert.throws(() => service.archive(actor, id), { message: 'not found' });
    }
  }
  assert.equal(snapshot(repo), before);
}

// Foreign-tenant visibility wins over ownership for editors.
{
  const { repo, service } = setup([{ id: 'f', tenant: 'b', owner: 'ed' }]);
  assert.throws(() => service.archive(editor, 'f'), { message: 'not found' });
  assert.equal(repo.documents[0].archived, false);
}

// Repeat archive is a no-op for permitted actors; permission still checked first.
{
  const { repo, service } = setup([{ id: 'r', tenant: 'a', owner: 'ed', archived: true }]);
  service.archive(editor, 'r');
  assert.deepEqual(repo.audit, []);
  assert.throws(() => service.archive(viewer, 'r'), { message: 'forbidden' });
  const { repo: repo2, service: s2 } = setup([{ id: 'r', tenant: 'a', owner: 'other', archived: true }]);
  assert.throws(() => s2.archive(editor, 'r'), { message: 'forbidden' });
  assert.deepEqual(repo2.audit, []);
  s2.archive(admin, 'r');
  assert.deepEqual(repo2.audit, []);
}

// Unknown role is denied.
{
  const { repo, service } = setup([{ id: 'u', tenant: 'a', owner: 'x' }]);
  assert.throws(() => service.archive({ tenant: 'a', user: 'x', role: 'root' }, 'u'), { message: 'forbidden' });
  assert.equal(repo.documents[0].archived, false);
}

console.log('authorization checks passed');

